if (UnityEngine.Application.dataPath != "D:/Program/Unity/Project Y/Assets") throw new System.Exception("Wrong Unity project");
if (UnityEditor.EditorApplication.isPlayingOrWillChangePlaymode || UnityEditor.EditorApplication.isCompiling || UnityEditor.EditorApplication.isUpdating) throw new System.Exception("Editor must be idle in Edit Mode");
