var rows=Newtonsoft.Json.Linq.JArray.Parse(System.IO.File.ReadAllText("Art/ProfessionArsenal20261025/Integration/models.json"));
var report=new Newtonsoft.Json.Linq.JArray();
foreach (var row in rows) {
    string path=(string)row["prefabPath"];
    var prefab=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.GameObject>(path);
    if(prefab==null)throw new System.Exception("Missing weapon prefab: "+path);
    var renderers=prefab.GetComponentsInChildren<UnityEngine.Renderer>(true);
    if(renderers.Length==0)throw new System.Exception("No renderer: "+path);
    var bounds=renderers[0].bounds;
    var materials=new Newtonsoft.Json.Linq.JArray();
    foreach(var renderer in renderers) {
        bounds.Encapsulate(renderer.bounds);
        foreach(var mat in renderer.sharedMaterials) {
            if(mat==null||mat.shader==null)throw new System.Exception("Unbound material: "+path);
            materials.Add(new Newtonsoft.Json.Linq.JObject {["name"]=mat.name,["assetPath"]=UnityEditor.AssetDatabase.GetAssetPath(mat),["shader"]=mat.shader.name});
        }
    }
    var importer=UnityEditor.AssetImporter.GetAtPath((string)row["modelPath"]) as UnityEditor.ModelImporter;
    if(importer==null||!importer.bakeAxisConversion||importer.globalScale!=1||importer.importAnimation)throw new System.Exception("Importer contract: "+path);
    if(bounds.size.y<.7f||bounds.size.y>2.5f)throw new System.Exception("Unexpected weapon scale: "+path);
    if(prefab.GetComponent<ProjectY.Samples.WeaponModelView>()==null)throw new System.Exception("Missing WeaponModelView");
    report.Add(new Newtonsoft.Json.Linq.JObject {["id"]=(int)row["id"],["prefabPath"]=path,["bounds"]=new Newtonsoft.Json.Linq.JArray(bounds.size.x,bounds.size.y,bounds.size.z),["materials"]=materials});
}
var result=new Newtonsoft.Json.Linq.JObject {["status"]="native_import_validated",["playMode"]=false,["count"]=report.Count,["weapons"]=report};
System.IO.File.WriteAllText("Art/ProfessionArsenal20261025/Integration/unity-import.json",result.ToString());
return result.ToString();
